-- The SUMO-CHAM code key (Code keys -> Drilling -> SUMO-CHAM), from the ISCAR
-- e-catalog's SUMO-CHAM families (ICP / ICM / ICK / ICN / ICG / IHP / QCP / HCP
-- heads, DCN / DCNS / DCNM / DCNT drill bodies); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.sumocham', $ck${"title": "SUMO-CHAM code key – drilling heads and drill bodies", "subtitle": "Exchangeable drilling heads (ICP, ICM, ICK, ICN, ICG, IHP, QCP, HCP) and the DCN drill bodies that carry them", "example": "ICP 040", "decoder": "sumo-cham", "sections": [{"key": "i-family", "title": "Head – family", "sample": "ICP", "rows": [{"code": "ICP", "meaning": "Heads for ISO P materials"}, {"code": "ICM", "meaning": "Heads for ISO M and ISO S materials"}, {"code": "ICK", "meaning": "Heads for ISO K materials"}, {"code": "ICN", "meaning": "Heads for ISO N materials"}, {"code": "ICG", "meaning": "Chip splitting heads for ISO M and ISO P materials"}, {"code": "IHP", "meaning": "Heads for ISO P materials (non-alloy and carbon steel); IHP-BD for construction beams and structural steel"}, {"code": "QCP", "meaning": "Self-centering heads for ISO P materials (single margin; -2M double margin)"}, {"code": "HCP", "meaning": "Self-centering heads for ISO P and ISO K materials (IQ line)"}]}, {"key": "i-dia", "title": "Head – drilling diameter", "sample": "040", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 040 = 4.0 mm, 329 = 32.9 mm)"}, {"code": "####", "meaning": "Drilling diameter x100 (e.g. 0635 = 6.35 mm, 1587 = 15.87 mm)"}]}, {"key": "i-suffix", "title": "Head – suffix", "rows": [{"code": "2M", "meaning": "Double margin, for high surface finish"}, {"code": "BD", "meaning": "For construction beams and structural steel (DCN ...-BD bodies)"}, {"code": "IQ", "meaning": "IQ line"}]}, {"key": "t-family", "title": "Drill body – family", "sample": "DCN", "rows": [{"code": "DCN", "meaning": "Drill body with exchangeable heads and internal coolant holes"}, {"code": "DCNS", "meaning": "Drill body without flange, one flat shank, suitable for chamfering holders"}, {"code": "DCNM", "meaning": "Modular drill with FLEX-FIT connection for multi-spindle and Swiss-type machines"}, {"code": "DCNT", "meaning": "Drill body with chamfering inserts, for pre-thread holes (M8 – M24)"}]}, {"key": "t-dia", "title": "Drill body – head size", "sample": "060", "rows": [{"code": "###", "meaning": "Smallest head diameter it carries x10 (e.g. 060 = heads 6.00 – 6.49 mm); DCNT: pre-thread hole diameter"}]}, {"key": "t-length", "title": "Drill body – length", "sample": "018", "rows": [{"code": "###", "meaning": "Usable length in mm (e.g. 018 = about 18 mm) (inferred)"}]}, {"key": "t-height", "title": "Drill body – shank diameter", "sample": "12", "rows": [{"code": "##", "meaning": "Shank diameter in mm (e.g. 12)"}, {"code": "###", "meaning": "DCNS: shank diameter x10 (e.g. 080 = 8 mm)"}]}, {"key": "t-shank", "title": "Drill body – shank type", "sample": "R", "rows": [{"code": "R", "meaning": "Cylindrical shank"}, {"code": "A", "meaning": "One flat shank"}, {"code": "C", "meaning": "Cylindrical shank (small diameters, Swiss-type) (inferred)"}, {"code": "N", "meaning": "WN shank, reinforced body (construction beams)"}, {"code": "B", "meaning": "One flat shank without flange (DCNS)"}]}, {"key": "t-depth", "title": "Drill body – drilling depth", "sample": "3D", "rows": [{"code": "#D", "meaning": "Drilling depth as a ratio of the diameter (e.g. 3D = 3xD)"}, {"code": "##D", "meaning": "Drilling depth as a ratio of the diameter (e.g. 12D = 12xD)"}, {"code": "#.#D", "meaning": "Drilling depth as a ratio of the diameter (1.5D = 1.5xD)"}]}, {"key": "t-connection", "title": "Drill body – connection", "rows": [{"code": "M##", "meaning": "FLEX-FIT thread connection (DCNM, e.g. M12)"}, {"code": "MMT##", "meaning": "MULTI-MASTER connection (e.g. MMT05)"}, {"code": "PICCO", "meaning": "PICCO connection"}]}, {"key": "t-thread", "title": "Drill body – thread", "rows": [{"code": "M##", "meaning": "DCNT: the thread the pre-thread hole is for (e.g. M8)"}]}, {"key": "t-suffix", "title": "Drill body – suffix", "rows": [{"code": "BD", "meaning": "For the construction beam industry (IHP-BD heads)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
